import bpy, bmesh, math, json
from mathutils import Vector

# SPEC is populated by the geometric outline preparation step; all distances in mm.
bpy.ops.object.select_all(action='SELECT')
bpy.ops.object.delete(use_global=False)
scene=bpy.context.scene
scene.unit_settings.system='METRIC'
scene.unit_settings.scale_length=1.0
scene.unit_settings.length_unit='MILLIMETERS'
parts=bpy.data.collections.new('PRINT — five black bases and red faces')
scene.collection.children.link(parts)
keys=bpy.data.collections.new('CONNECTORS — six recessed snap keys')
scene.collection.children.link(keys)
studio=bpy.data.collections.new('STUDIO — camera and lighting')
scene.collection.children.link(studio)

def material(name,color):
    m=bpy.data.materials.new(name);m.diffuse_color=(*color,1);m.use_nodes=True
    p=m.node_tree.nodes.get('Principled BSDF');p.inputs['Base Color'].default_value=(*color,1)
    p.inputs['Roughness'].default_value=.6
    p.inputs['Specular IOR Level'].default_value=.18
    return m
black=material('01 • Creality Hyper PLA • black',(0.012,0.014,0.017))
red=material('02 • Soyelin Ultra PLA • red',(.62,.007,.023))

def mesh_object(name,verts,faces,mat,collection=parts):
    mesh=bpy.data.meshes.new(name+' mesh');mesh.from_pydata([(x*.001,y*.001,z*.001) for x,y,z in verts],[],faces);mesh.update()
    bm=bmesh.new();bm.from_mesh(mesh);bmesh.ops.recalc_face_normals(bm,faces=list(bm.faces));bmesh.ops.triangulate(bm,faces=list(bm.faces));bm.to_mesh(mesh);bm.free()
    o=bpy.data.objects.new(name,mesh);collection.objects.link(o)
    if mat:o.data.materials.append(mat)
    return o

def prism(name,ring,z0,z1,mat,collection=parts):
    n=len(ring);v=[(x,y,z) for z in (z0,z1) for x,y in ring]
    faces=[tuple(range(n-1,-1,-1)),tuple(range(n,2*n))]
    faces += [(i,(i+1)%n,(i+1)%n+n,i+n) for i in range(n)]
    return mesh_object(name,v,faces,mat,collection)

def loft(name,rings,heights,mat,collection=parts):
    n=len(rings[0]);v=[(x,y,z) for r,z in zip(rings,heights) for x,y in r]
    f=[tuple(range(n-1,-1,-1)),tuple(range((len(rings)-1)*n,len(rings)*n))]
    for j in range(len(rings)-1):
        for i in range(n):f.append((j*n+i,j*n+(i+1)%n,(j+1)*n+(i+1)%n,(j+1)*n+i))
    return mesh_object(name,v,f,mat,collection)

def boolean(target,tool,operation='DIFFERENCE'):
    m=target.modifiers.new('Manufactured solid — '+operation,'BOOLEAN');m.operation=operation;m.solver='EXACT';m.object=tool
    bpy.context.view_layer.objects.active=target
    bpy.ops.object.modifier_apply(modifier=m.name)
    bpy.data.objects.remove(tool,do_unlink=True)

def rot_ring(r,c):
    a=math.radians(c.get('angle',0));co,si=math.cos(a),math.sin(a)
    return [(c['x']+x*co-y*si,c['y']+x*si+y*co) for x,y in r]

def pocket(c):
    def ring(extra):
        return [(-18.3,-7.2-extra),(-5,-4.2-extra),(5,-4.2-extra),(18.3,-7.2-extra),(18.3,7.2+extra),(5,4.2+extra),(-5,4.2+extra),(-18.3,7.2+extra)]
    r=[rot_ring(ring(e),c) for e in (0,0,.6,.6)]
    return loft('temporary recessed key socket',r,[-.1,.8,1.4,3.2],None)

panel_objects={}
for panel in SPEC['panels']:
    pid=panel['id'];outer=panel['base'][0]['outer']
    base=prism(pid+' • BLACK base',outer,0,6,black)
    base['part_id']=pid;base['print_material']='black';base['print_orientation']='flat back on bed, Z=0';base['nominal_units']='millimeters'
