# Four long in-plane flexures. The widened upper section snaps past the socket lip.
# Replaceable keys make fit calibration independent of the large wall panels.
key_profile=[(-18,-7),(-5,-4),(5,-4),(18,-7),(18,-5.5),(6.5,-2.5),(6.5,2.5),(18,5.5),(18,7),(5,4),(-5,4),(-18,7),(-18,5.5),(-6.5,2.5),(-6.5,-2.5),(-18,-5.5)]
outer_indices={0,1,2,3,8,9,10,11}
def snap_key(name,c,adjust=0,zbase=.2):
    rings=[]
    for extra in [0,0,.45,.45,0]:
        r=[]
        for i,(x,y) in enumerate(key_profile):
            y+=math.copysign(adjust+(extra if i in outer_indices else 0),y)
            r.append((x,y))
        rings.append(rot_ring(r,c))
    key=loft(name,rings,[zbase,zbase+.6,zbase+1.0,zbase+1.4,zbase+2.6],black,keys)
    key['print_material']='black';key['snap_fit']='Prototype fit: print coupon before the full panels.'
    return key

